const input = (items[0] && items[0].json) || {};
const constants = {
  workflow_version: 'psy_05_terms_questions_v5',
  workflow_name: 'psy_05_terms_questions',
  llm_model: 'deepseek-flash',
  thinking: { type: 'disabled' },
  temperature_terms: 0.2,
  temperature_questions: 0.5,
  max_output_tokens: 8000,
  // DeepSeek peak prices, USD per 1M tokens (conservative; off-peak discount ignored).
  prices_usd_per_1m: { tier: 'peak', miss: 0.3, hit: 0.006, out: 1.2 },
  monthly_budget_usd: 5,
  budget_stop_ratio: 0.8,
  max_cost_usd_per_lecture: 0.3,
  chars_per_token: 2,
  terms_max_input_tokens: 80000,
  est_output_tokens_terms: 6000,
  est_output_tokens_questions: 6000,
  est_input_tokens_questions: 8000,
  est_subtopics_for_budget: 8,
  questions_target: 10,
  max_questions_per_subtopic: 14,
  questions_konspekt_max_chars: 5500,
  questions_transcript_max_chars: 7000,
  questions_thin_min_chars: 400,
  prompt_versions: { terms: 'extract_terms_v2', questions: 'gen_questions_v3' },
  max_attempts: 3,
  stale_running_hours: 4,
};
// In — Execute may only LOWER these limits (never raise).
['max_cost_usd_per_lecture', 'monthly_budget_usd'].forEach((key) => {
  const v = Number(input[key]);
  if (Number.isFinite(v) && v > 0 && v < constants[key]) constants[key] = v;
});
return [{ json: { constants }, pairedItem: 0 }];

const C = $('Run — Init Constants').first().json.constants;
const row = items[0].json;
const SYSTEM = "Ты выделяешь подтемы и термины одной лекции. Источник — только блоки этого сообщения. Не добавляй понятия, определения и примеры из других лекций и из общих знаний.\n\nВход:\nМЕТАДАННЫЕ\nГЛОССАРИЙ — уже известные написания, может быть пуст\nКОНСПЕКТ\nТРАНСКРИПТ\n\nПравила:\n- Подтема — отдельный учебный узел этой лекции, в порядке изложения. ordinal с 1. Не дроби лекцию на одну подтему и не копируй оглавление чужого курса.\n- Термин — имя понятия, которое лектор здесь употребляет. Бытовые слова, имена людей и разовый пример термином не являются.\n- definition — только формулировка из этой лекции. Нет формулировки — null. Дыру `[неразборчиво]` не раскрывай.\n- life_example — 1–2 предложения бытовой ситуации, которая иллюстрирует definition из этой лекции. Не вводит новых фактов. Если definition = null, то life_example = null.\n- canonical — написание из ГЛОССАРИЙ, если термин там есть; иначе как в конспекте.\n- aliases — только другие написания из глоссария или явная оговорка лектора. Не выдумывай варианты.\n- subtopic_ordinal — подтема, в которой термин разбирается. Нет явной подтемы — ближайшая по тексту.\n\nОтвет — один JSON-объект без Markdown и без текста вокруг:\n\n{\"subtopics\":[{\"ordinal\":1,\"title\":\"...\"}],\"terms\":[{\"canonical\":\"...\",\"aliases\":[],\"definition\":null,\"life_example\":null,\"subtopic_ordinal\":1}]}\n\nПустая лекция — пустые массивы. Не объясняй ответ.";
const cpt = C.chars_per_token || 2;
const est = (s) => Math.ceil(String(s || '').length / cpt);

const metaLines = ['МЕТАДАННЫЕ', 'Название: ' + (row.title || '[неизвестно]')];
if (row.duration_sec) metaLines.push('Длительность: ' + Math.round(Number(row.duration_sec) / 60) + ' мин');
if (row.lecturer_name) metaLines.push('Лектор: ' + row.lecturer_name);
const head = [
  metaLines.join('\n'),
  'ГЛОССАРИЙ\n' + (row.glossary || ''),
  'КОНСПЕКТ\n' + String(row.konspekt_md || '').trim(),
].join('\n\n');

let transcript = String(row.transcript || '').trim();
let truncated = false;
const room = (C.terms_max_input_tokens - est(SYSTEM) - est(head) - 200) * cpt;
if (transcript.length > room) {
  transcript = transcript.slice(0, Math.max(room, 0)) + '\n[транскрипт усечён по лимиту токенов]';
  truncated = true;
}
const user = head + '\n\nТРАНСКРИПТ\n' + transcript;

const P = C.prices_usd_per_1m;
const inTokens = est(SYSTEM) + est(user);
const termsCost = (inTokens * P.miss + C.est_output_tokens_terms * P.out) / 1e6;
const questionCall = (C.est_input_tokens_questions * P.miss + C.est_output_tokens_questions * P.out) / 1e6;
const projected = termsCost + C.est_subtopics_for_budget * questionCall;
const spentLecture = Number(row.spent_lecture_usd) || 0;
const spentMonth = Number(row.spent_month_usd) || 0;
const lectureCap = C.max_cost_usd_per_lecture;
const monthCap = C.monthly_budget_usd * C.budget_stop_ratio;
let reason = null;
if (spentLecture + projected > lectureCap) {
  reason = 'budget_exceeded: лимит на лекцию ' + lectureCap + ' USD (потрачено ' + spentLecture.toFixed(4)
    + ', прогноз терминов+вопросов ' + projected.toFixed(4) + ')';
} else if (spentMonth + projected > monthCap) {
  reason = 'budget_exceeded: 80% месячного бюджета ' + C.monthly_budget_usd + ' USD (потрачено '
    + spentMonth.toFixed(4) + ', прогноз ' + projected.toFixed(4) + ')';
}
if (reason) {
  return [{ json: { budget_exceeded: true, error_message: reason, lecture_id: row.lecture_id, job_id: row.job_id }, pairedItem: 0 }];
}
return [{
  json: {
    budget_exceeded: false,
    lecture_id: row.lecture_id,
    job_id: row.job_id,
    course_id: row.course_id,
    step: 'terms',
    prompt_version: C.prompt_versions.terms,
    transcript_truncated: truncated,
    projected_cost_usd: Number(projected.toFixed(5)),
    request_body: {
      model: C.llm_model,
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: user },
      ],
      thinking: C.thinking,
      response_format: { type: 'json_object' },
      max_tokens: C.max_output_tokens,
      temperature: C.temperature_terms,
      stream: false,
    },
  },
  pairedItem: 0,
}];

const C = $('Run — Init Constants').first().json.constants;
const src = $('LLM — Build Terms Request').first().json;
function parseDeepSeek(resp, C, src, step, promptVersion) {
  const r = resp || {};
  const choice = (r.choices && r.choices[0]) || {};
  const content = String((choice.message && choice.message.content) || '');
  const u = r.usage || {};
  const hit = Number(u.prompt_cache_hit_tokens != null
    ? u.prompt_cache_hit_tokens
    : ((u.prompt_tokens_details && u.prompt_tokens_details.cached_tokens) || 0)) || 0;
  let miss = u.prompt_cache_miss_tokens != null ? Number(u.prompt_cache_miss_tokens) : null;
  const promptTokens = Number(u.prompt_tokens != null ? u.prompt_tokens : ((miss || 0) + hit)) || 0;
  if (miss == null || !Number.isFinite(miss)) miss = Math.max(promptTokens - hit, 0);
  const completion = Number(u.completion_tokens) || 0;
  const P = C.prices_usd_per_1m;
  const costExact = (miss * P.miss + hit * P.hit + completion * P.out) / 1e6;
  return {
    content,
    finish_reason: choice.finish_reason || null,
    cost_exact: costExact,
    usage_row: {
      lecture_id: src.lecture_id,
      job_id: src.job_id,
      workflow_name: C.workflow_name,
      workflow_version: C.workflow_version,
      model: r.model || C.llm_model,
      prompt_tokens: promptTokens,
      completion_tokens: completion,
      cost_usd: Number(costExact.toFixed(6)),
      prompt_version: promptVersion,
      prompt_cache_hit_tokens: hit,
      step,
    },
  };
}
const p = parseDeepSeek(items[0].json, C, src, 'terms', C.prompt_versions.terms);

function parseJson(text) {
  let t = String(text || '').trim();
  const m = t.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/);
  if (m) t = m[1];
  try {
    return { value: JSON.parse(t) };
  } catch (e) {
    const a = t.indexOf('{');
    const b = t.lastIndexOf('}');
    if (a >= 0 && b > a) {
      try {
        return { value: JSON.parse(t.slice(a, b + 1)) };
      } catch (e2) {
        /* fall through */
      }
    }
    return { error: 'invalid_json' };
  }
}

const result = {
  lecture_id: src.lecture_id,
  job_id: src.job_id,
  usage_row: p.usage_row,
  cost_exact: p.cost_exact,
  finish_reason: p.finish_reason,
  transcript_truncated: src.transcript_truncated,
  ok: false,
  error_message: null,
  subtopics: [],
  terms: [],
};

function fail(msg) {
  result.error_message = msg;
  return [{ json: result, pairedItem: 0 }];
}

if (!p.content.trim()) return fail('llm_empty_response (terms)');
const pj = parseJson(p.content);
if (pj.error) {
  return fail(p.finish_reason === 'length' ? 'llm_truncated: finish_reason=length (terms)' : 'terms: invalid_json');
}
const data = pj.value;
if (!data || typeof data !== 'object' || !Array.isArray(data.subtopics) || !Array.isArray(data.terms)) {
  return fail('terms: schema (нужны subtopics[] и terms[])');
}

const subs = [];
const seen = new Set();
for (const s of data.subtopics) {
  const ordinal = Number(s && s.ordinal);
  const title = String((s && s.title) || '').trim();
  if (!Number.isInteger(ordinal) || ordinal < 1 || !title || seen.has(ordinal)) continue;
  seen.add(ordinal);
  subs.push({ ordinal, title });
}
subs.sort((a, b) => a.ordinal - b.ordinal);
// empty_subtopics is soft: Terms Ready / course fallback may synthesize a subtopic.
// Do not Fail Context the whole lecture here.

const byKey = new Map();
for (const t of data.terms) {
  const canonical = String((t && t.canonical) || '').trim();
  if (!canonical) continue;
  const aliases = Array.isArray(t.aliases)
    ? t.aliases.map((a) => String(a || '').trim()).filter((a) => a && a !== canonical)
    : [];
  let definition = t.definition == null ? null : String(t.definition).trim() || null;
  let lifeExample = definition && t.life_example != null ? String(t.life_example).trim() || null : null;
  let so = Number(t.subtopic_ordinal);
  if (!seen.has(so)) {
    const lower = subs.filter((s) => s.ordinal <= so).pop();
    so = lower ? lower.ordinal : subs[0].ordinal;
  }
  const key = canonical.toLowerCase();
  if (byKey.has(key)) {
    const prev = byKey.get(key);
    prev.aliases = Array.from(new Set(prev.aliases.concat(aliases)));
    if (!prev.definition && definition) {
      prev.definition = definition;
      prev.life_example = lifeExample;
    }
    continue;
  }
  byKey.set(key, { canonical, aliases: Array.from(new Set(aliases)), definition, life_example: lifeExample, subtopic_ordinal: so });
}
const terms = Array.from(byKey.values());
// empty_terms is soft when subtopics exist (or even when not): course glossary
// fallback is applied in LLM — Terms Ready via finalizeTermsExtractGate.
result.ok = true;
result.subtopics = subs;
result.terms = terms;
result.lecture_terms_empty = terms.length === 0;
if (!subs.length) {
  result.error_message = 'terms: empty_subtopics';
}
if (!terms.length) {
  result.error_message = result.error_message || 'terms: empty_terms';
}
return [{ json: result, pairedItem: 0 }];

/**
 * Fragment picking + thin-subtopic merge for psy_05.
 * Pure helpers — used from n8n Code (embedded) and node:test.
 */

const DEFAULTS = {
  konspektMaxChars: 5500,
  transcriptMaxChars: 7000,
  thinMinChars: 400,
  titleTokenMinLen: 5,
  transcriptChunkChars: 1000,
};

function norm(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/ё/g, 'е');
}

/** Significant tokens from a title/phrase — no short 4-char stems. */
function titleTokens(phrase, minLen = DEFAULTS.titleTokenMinLen) {
  return norm(phrase)
    .split(/[^а-яa-z0-9]+/)
    .filter((w) => w.length >= minLen);
}

function sectionList(konspekt) {
  const text = String(konspekt || '').trim();
  if (!text) return [];
  return text.split(/\n(?=##\s)/).map((s) => s.trim()).filter(Boolean);
}

function scoreSection(sectionText, title, terms) {
  const t = norm(sectionText);
  let score = 0;
  const tokens = titleTokens(title);
  for (const tok of tokens) {
    if (t.includes(tok)) score += 3;
  }
  const heading = (sectionText.split('\n')[0] || '');
  const h = norm(heading);
  if (tokens.length && tokens.every((tok) => h.includes(tok))) score += 8;
  for (const term of terms || []) {
    const names = [term.canonical].concat(term.aliases || []).map(norm).filter(Boolean);
    for (const name of names) {
      if (name.length >= 4 && t.includes(name)) score += 2;
    }
  }
  return score;
}

function missWindowCenter(sectionsLength, opts = {}) {
  if (sectionsLength <= 0) return 0;
  const idx = opts.subtopicIndex;
  const count = opts.subtopicCount;
  if (idx == null || count == null || count < 1) {
    return Math.min(sectionsLength - 1, Math.max(0, Math.floor(sectionsLength / 2)));
  }
  const i = Math.min(Math.max(Number(idx) || 0, 0), Math.max(count - 1, 0));
  if (count <= 1 || sectionsLength <= 1) return 0;
  return Math.min(
    sectionsLength - 1,
    Math.max(0, Math.round((i / (count - 1)) * (sectionsLength - 1))),
  );
}

/**
 * Pick konspekt fragment for one subtopic: best matching ## section ± neighbour,
 * capped. Never falls back to the whole konspekt.
 * opts: { subtopicIndex, subtopicCount } — center miss-window by subtopic position.
 */
function pickKonspektFragment(konspekt, title, terms, maxChars = DEFAULTS.konspektMaxChars, opts = {}) {
  const sections = sectionList(konspekt);
  if (!sections.length) {
    return { text: '', matched: false, score: 0 };
  }
  const scored = sections.map((text, idx) => ({
    idx,
    text,
    score: scoreSection(text, title, terms),
  }));
  scored.sort((a, b) => b.score - a.score || a.idx - b.idx);
  const best = scored[0];
  if (!best || best.score <= 0) {
    const approx = missWindowCenter(sections.length, opts);
    const window = [sections[approx]];
    if (approx > 0) window.unshift(sections[approx - 1]);
    if (approx + 1 < sections.length) window.push(sections[approx + 1]);
    let text = window.join('\n\n');
    if (text.length > maxChars) text = text.slice(0, maxChars);
    return { text, matched: false, score: 0 };
  }
  const idxs = new Set([best.idx]);
  if (best.idx > 0) idxs.add(best.idx - 1);
  if (best.idx + 1 < sections.length) idxs.add(best.idx + 1);
  let text = Array.from(idxs)
    .sort((a, b) => a - b)
    .map((i) => sections[i])
    .join('\n\n');
  if (text.length > maxChars) {
    const primary = sections[best.idx];
    if (primary.length >= maxChars) {
      text = primary.slice(0, maxChars);
    } else {
      text = text.slice(0, maxChars);
    }
  }
  return { text, matched: true, score: best.score };
}

function textMatches(haystack, title, terms) {
  const t = norm(haystack);
  if (!t) return false;
  const tokens = titleTokens(title);
  if (tokens.length && tokens.every((tok) => t.includes(tok))) return true;
  if (tokens.some((tok) => t.includes(tok))) return true;
  for (const term of terms || []) {
    const names = [term.canonical].concat(term.aliases || []).map(norm).filter(Boolean);
    for (const name of names) {
      if (name.length >= 5 && t.includes(name)) return true;
    }
  }
  return false;
}

function transcriptToSegments(chunks, transcript, chunkChars = DEFAULTS.transcriptChunkChars) {
  let segs = (Array.isArray(chunks) ? chunks : [])
    .map((c) => String((c && c.text) || '').trim())
    .filter(Boolean);
  if (segs.length) return segs;
  const tr = String(transcript || '');
  if (!tr.trim()) return [];
  segs = [];
  for (let i = 0; i < tr.length; i += chunkChars) {
    segs.push(tr.slice(i, i + chunkChars));
  }
  return segs;
}

/**
 * Transcript: only matching segments ±1 neighbour, capped.
 * If chunks empty, slice raw transcript into ~1000-char pieces first.
 */
function pickTranscriptFragment(
  chunks,
  title,
  terms,
  maxChars = DEFAULTS.transcriptMaxChars,
  transcript = '',
  opts = {},
) {
  const segs = transcriptToSegments(chunks, transcript);
  if (!segs.length) {
    return { text: '', matched: false };
  }
  const hit = new Set();
  segs.forEach((text, i) => {
    if (textMatches(text, title, terms)) {
      hit.add(i);
      if (i > 0) hit.add(i - 1);
      if (i + 1 < segs.length) hit.add(i + 1);
    }
  });
  // No lexical hit: positional window by subtopic index (same idea as konspekt miss).
  let order = Array.from(hit).sort((a, b) => a - b);
  if (!order.length && segs.length) {
    const mid = missWindowCenter(segs.length, opts);
    order = [mid];
    if (mid > 0) order.unshift(mid - 1);
    if (mid + 1 < segs.length) order.push(mid + 1);
    order.sort((a, b) => a - b);
  }
  const parts = [];
  let used = 0;
  for (const i of order) {
    const text = segs[i];
    if (!text) continue;
    if (used + text.length > maxChars) break;
    parts.push(text);
    used += text.length + 1;
  }
  return {
    text: parts.length ? parts.join('\n') : '',
    matched: hit.size > 0,
  };
}

function termsForOrdinal(terms, ordinal) {
  return (terms || []).filter((t) => Number(t.subtopic_ordinal) === Number(ordinal));
}

function termsWithDefinition(terms) {
  return (terms || []).filter((t) => t && t.definition != null && String(t.definition).trim() !== '');
}

/**
 * Resolve term list for MCQ:
 * subtopic (with definition) → lecture → course glossary.
 * Empty after the whole chain → no LLM.
 */
function resolveTermsForSubtopic(ordinal, lectureTerms, courseTerms = []) {
  const own = termsWithDefinition(termsForOrdinal(lectureTerms, ordinal));
  if (own.length) {
    return { terms: own, fallback: false, source: 'subtopic' };
  }
  const lecture = termsWithDefinition(lectureTerms);
  if (lecture.length) {
    return { terms: lecture, fallback: true, source: 'lecture' };
  }
  const course = termsWithDefinition(courseTerms);
  if (course.length) {
    return { terms: course, fallback: true, source: 'course' };
  }
  return { terms: [], fallback: false, source: null };
}

/**
 * Merge only when a matched primary ## section exists and its length (no neighbours) < thinMin.
 * score 0 (no match) ≠ thin — leave the subtopic alone.
 */
function mergeThinSubtopics(subtopics, terms, konspekt, opts = {}) {
  const thinMin = opts.thinMinChars != null ? opts.thinMinChars : DEFAULTS.thinMinChars;
  let list = (subtopics || [])
    .map((s) => ({ ordinal: Number(s.ordinal), title: String(s.title || '').trim() }))
    .filter((s) => s.ordinal >= 1 && s.title)
    .sort((a, b) => a.ordinal - b.ordinal);

  if (list.length <= 1) {
    return { subtopics: list, terms: (terms || []).slice(), merges: [] };
  }

  const merges = [];
  let changed = true;
  while (changed && list.length > 1) {
    changed = false;
    for (let i = 0; i < list.length; i++) {
      const sub = list[i];
      const ownTerms = termsForOrdinal(terms, sub.ordinal);
      const sections = sectionList(konspekt);
      const scored = sections.map((text, idx) => ({
        idx,
        text,
        score: scoreSection(text, sub.title, ownTerms),
      }));
      scored.sort((a, b) => b.score - a.score || a.idx - b.idx);
      // No matched section → not thin; do not merge.
      if (!scored[0] || scored[0].score <= 0) continue;
      const primaryChars = scored[0].text.length;
      if (primaryChars >= thinMin) continue;

      let targetIdx = i > 0 ? i - 1 : i + 1;
      if (i > 0 && i + 1 < list.length) {
        const prevOwn = termsForOrdinal(terms, list[i - 1].ordinal);
        const nextOwn = termsForOrdinal(terms, list[i + 1].ordinal);
        const prevPrimary = sections
          .map((text) => ({ text, score: scoreSection(text, list[i - 1].title, prevOwn) }))
          .sort((a, b) => b.score - a.score)[0];
        const nextPrimary = sections
          .map((text) => ({ text, score: scoreSection(text, list[i + 1].title, nextOwn) }))
          .sort((a, b) => b.score - a.score)[0];
        const prevLen = prevPrimary && prevPrimary.score > 0 ? prevPrimary.text.length : 0;
        const nextLen = nextPrimary && nextPrimary.score > 0 ? nextPrimary.text.length : 0;
        targetIdx = nextLen > prevLen ? i + 1 : i - 1;
      }
      const target = list[targetIdx];
      merges.push({
        from_ordinal: sub.ordinal,
        from_title: sub.title,
        into_ordinal: target.ordinal,
        into_title: target.title,
        fragment_chars: primaryChars,
      });
      target.title = target.title + ' / ' + sub.title;
      const fromOrd = sub.ordinal;
      const intoOrd = target.ordinal;
      terms = (terms || []).map((t) => {
        if (Number(t.subtopic_ordinal) === fromOrd) {
          return { ...t, subtopic_ordinal: intoOrd };
        }
        return t;
      });
      list.splice(i, 1);
      changed = true;
      break;
    }
  }

  const ordMap = new Map();
  list = list.map((s, idx) => {
    const neu = idx + 1;
    ordMap.set(s.ordinal, neu);
    return { ordinal: neu, title: s.title };
  });
  const remappedTerms = (terms || []).map((t) => {
    const old = Number(t.subtopic_ordinal);
    const neu = ordMap.has(old) ? ordMap.get(old) : old;
    return { ...t, subtopic_ordinal: neu };
  });

  return { subtopics: list, terms: remappedTerms, merges };
}

/**
 * After extract_terms: decide whether to enter the subtopic loop.
 *
 * Soft (proceed=true): parseOk=true with empty lecture terms and/or empty subtopics.
 *   - course glossary has definitions → keep/synthesize subtopics, course_fallback.
 *   - nowhere defined → synthesize one subtopic only if list empty → no_terms_available.
 *
 * Hard (proceed=false): parseOk=false (invalid_json / llm_truncated / empty / schema).
 *   → Fail Context (retryable). No synthetic subtopic, no course MCQ.
 */
function finalizeTermsExtractGate(input) {
  const {
    parseOk,
    errorMessage = null,
    subtopics = [],
    terms = [],
    courseTerms = [],
    lectureTitle = '',
  } = input || {};
  const courseDefined = termsWithDefinition(courseTerms);
  const title = String(lectureTitle || '').trim() || 'Лекция';
  let subs = (subtopics || [])
    .map((s) => ({ ordinal: Number(s.ordinal), title: String(s.title || '').trim() }))
    .filter((s) => s.ordinal >= 1 && s.title)
    .sort((a, b) => a.ordinal - b.ordinal);

  // Hard parse failure → Fail Context (retryable). Do not invent a subtopic
  // (would wipe real ones on regenerate) and do not hide the error behind course MCQ.
  if (!parseOk) {
    return {
      proceed: false,
      subtopics: [],
      terms: [],
      reason: errorMessage || 'terms_extract_failed',
      lecture_terms_empty: true,
      course_fallback: false,
      hard_parse_error: true,
    };
